import { mapGetters, mapActions } from 'vuex';
export default {
  name: 'ContactPage',
  computed: {
    ...mapGetters(['currentWeather']),
    weatherRows() {
      if (!this.currentWeather || !this.currentWeather.daily) return [];
      const {
        time,
        temperature_2m_max,
        temperature_2m_min,
        weathercode
      } = this.currentWeather.daily;
      return time.map((date, index) => ({
        date,
        maxTemp: temperature_2m_max[index],
        minTemp: temperature_2m_min[index],
        weathercode: weathercode[index]
      }));
    },
    fields() {
      return [{
        key: 'date',
        label: 'Дата'
      }, {
        key: 'minTemp',
        label: 'Мін. темп. (°C)'
      }, {
        key: 'maxTemp',
        label: 'Макс. темп. (°C)'
      }, {
        key: 'icon',
        label: 'Погода'
      }];
    }
  },
  methods: {
    ...mapActions(['fetchWeatherForecast']),
    updateWeather() {
      this.fetchWeatherForecast();
    },
    getIcon(code) {
      const icons = {
        0: '☀️',
        1: '🌤️',
        2: '⛅',
        3: '☁️',
        45: '🌫️',
        48: '🌫️',
        51: '🌦️',
        61: '🌧️',
        71: '🌨️',
        80: '🌦️',
        95: '⛈️',
        99: '🌩️'
      };
      return `https://twemoji.maxcdn.com/v/13.1.0/72x72/${this.emojiToCode(icons[code] || '❓')}.png`;
    },
    emojiToCode(emoji) {
      return Array.from(emoji).map(char => char.codePointAt(0).toString(16)).join('-');
    }
  },
  mounted() {
    this.fetchWeatherForecast();
  }
};
